 1	/**
 2	 * A deploy replaces .next's static chunk files under new content hashes. A
 3	 * browser tab left open across that deploy still holds JS referencing the
 4	 * OLD hashes, so the next code-split import 404s — a webpack ChunkLoadError
 5	 * (or, on some browsers/bundler paths, "Failed to fetch dynamically imported
 6	 * module"). This isn't a real app bug, just a stale asset reference, and a
 7	 * plain reload fixes it since the page then fetches the current build.
 8	 * Confirmed live 2026-09-02 on /admin/inbox right after a promote.
 9	 */
10	export function isChunkLoadError(error: Error): boolean {
11	  return (
12	    error.name === "ChunkLoadError" ||
13	    /Loading chunk [\d]+ failed/i.test(error.message) ||
14	    /Failed to fetch dynamically imported module/i.test(error.message) ||
15	    /Importing a module script failed/i.test(error.message)
16	  );
17	}
