19	const RELOAD_AT_KEY = "nxeon:chunk-reload-at";
20	const RELOAD_COOLDOWN_MS = 15_000;
21	
22	/** Reloads once per cooldown window — if the reload doesn't fix it (a real
23	 *  outage, not a stale chunk), this stops retrying and lets the normal error
24	 *  UI show instead of silently looping reloads forever. */
25	export function reloadForChunkErrorOnce(): boolean {
26	  if (typeof window === "undefined") return false;
27	  const last = Number(sessionStorage.getItem(RELOAD_AT_KEY) ?? 0);
28	  const now = Date.now();
29	  if (now - last < RELOAD_COOLDOWN_MS) return false;
30	  sessionStorage.setItem(RELOAD_AT_KEY, String(now));
31	  window.location.reload();
32	  return true;
33	}
