 12	/**
 13	 * Image upload for <ChatWidget/>.
 14	 *
 15	 * POST /api/chat/upload  (multipart/form-data: visitorId, file, optional body,
 16	 * optional name/email) — attaches an image to the visitor's OPEN conversation
 17	 * (created if none), exactly like POST /api/chat but carrying an image.
 18	 *
 19	 * Authorization mirrors POST /api/chat: the conversation is scoped strictly by
 20	 * the client-supplied `visitorId`, so a visitor can only ever attach to their
 21	 * own thread. The image is validated by signature (not the client-declared
 22	 * type) in lib/chat-attachment — SVG and non-images are rejected. Bytes live in
 23	 * Postgres. Per-IP rate limited.
 24	 */
 25	
 26	function clip(v: unknown, max: number): string | null {
 27	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
 28	}
 29	
 30	export async function POST(req: Request) {
 31	  const rl = checkRateLimit(`chat-upload:${trustedClientIp(req)}`, { max: 15, windowMs: 60_000 });
 32	  if (!rl.ok) {
 33	    return NextResponse.json(
 34	      { error: "Too many uploads. Please slow down." },
 35	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
 36	    );
 37	  }
 38	
 39	  let form: FormData;
 40	  try {
 41	    form = await req.formData();
 42	  } catch {
 43	    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
 44	  }
 45	
 46	  const visitorId = clip(form.get("visitorId"), 100);
 47	  const body = clip(form.get("body"), 5000) ?? "";
 48	  const name = clip(form.get("name"), 120);
 49	  const email = clip(form.get("email"), 200);
 50	  const conversationId = clip(form.get("conversationId"), 40);
 51	  const file = form.get("file");
 52	
 53	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
 54	  if (!(file instanceof File)) return NextResponse.json({ error: "No image provided." }, { status: 400 });
 55	  // Cheap guard before buffering the whole body into memory.
 56	  if (file.size > MAX_ATTACHMENT_BYTES) {
 57	    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
 58	  }
 59	
 60	  const bytes = Buffer.from(await file.arrayBuffer());
 61	  const check = validateImageBytes(bytes, file.type);
 62	  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });
 63	
 64	  const user = await currentUser();
 65	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
 66	    user?.id ? [{ userId: user.id }] : [],
 67	  );
 68	
 69	  // Continue the named conversation (if owned), else start a new one — mirrors
 70	  // POST /api/chat.
 71	  let convo = conversationId
 72	    ? await db.chatConversation.findFirst({
 73	        where: { id: conversationId, OR: ownedBy },
 74	        select: { id: true, name: true, email: true },
 75	      })
 76	    : null;
 77	
 78	  if (!convo) {
 79	    // Anonymous visitors must identify before starting (mirrors POST /api/chat).
 80	    if (!user) {
 81	      const nm = name ?? null;
 82	      const em = email ?? null;
 83	      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
 84	        return NextResponse.json(
 85	          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
 86	          { status: 400 },
 87	        );
 88	      }
 89	    }
 90	    convo = await db.chatConversation.create({
 91	      data: {
 92	        visitorId,
 93	        userId: user?.id ?? null,
 94	        name: name ?? user?.name ?? null,
 95	        email: email ?? user?.email ?? null,
 96	      },
 97	      select: { id: true, name: true, email: true },
 98	    });
 99	  }
100	
101	  const convoId = convo.id;
102	  await db.$transaction(async (tx) => {
103	    const msg = await tx.chatMessage.create({
104	      data: { conversationId: convoId, sender: "visitor", body },
105	    });
106	    await tx.chatAttachment.create({
107	      data: {
108	        messageId: msg.id,
109	        mime: check.mime,
110	        sizeBytes: check.bytes.length,
111	        data: new Uint8Array(check.bytes),
112	      },
113	    });
114	    await tx.chatConversation.update({
115	      where: { id: convoId },
116	      data: {
117	        status: "OPEN",
118	        unreadForAgent: true,
119	        lastMessageAt: new Date(),
120	        ...(user?.id ? { userId: user.id } : {}),
121	        ...(name && !convo!.name ? { name } : {}),
122	        ...(email && !convo!.email ? { email } : {}),
123	      },
124	    });
125	  });
126	
127	  // Discord bridge (Phase 1 mirror): best-effort, never blocks the upload —
128	  // no image bytes are forwarded (see lib/discord-bridge.ts), just a
129	  // placeholder plus any caption.
130	  await mirrorChatMessageToDiscord(convoId, body ? `📎 ${body}` : "📎 (image attachment — view in the chat widget/admin)", "visitor");
131	
132	  // Let the assistant look at the image (Claude vision) and reply, before we
133	  // return — so the bot's answer rides back on this response. Best-effort.
134	  try {
135	    const { runAssistant } = await import("@/lib/kb-run");
136	    await runAssistant({
137	      conversationId: convoId,
138	      visitorId,
139	      currentBody: body,
140	      images: [{ mediaType: check.mime, dataB64: Buffer.from(check.bytes).toString("base64") }],
141	    });
142	  } catch {
143	    /* assistant is non-essential */
144	  }
145	
146	  const full = await db.chatConversation.findUnique({
147	    where: { id: convoId },
148	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
149	  });
150	
151	  return NextResponse.json(
152	    {
153	      conversation: full
154	        ? { id: full.id, status: full.status, name: full.name, email: full.email }
155	        : null,
156	      messages: (full?.messages ?? []).map((m) => ({
157	        id: m.id,
158	        sender: m.sender,
159	        body: m.body,
160	        createdAt: m.createdAt.toISOString(),
161	        attachment: m.attachment
162	          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
163	          : null,
164	      })),
165	    },
166	    { headers: NO_STORE_HEADERS },
167	  );
168	}

