 31	}: {
 32	  searchParams: Promise<{ ticket?: string; dm?: string }>;
 33	}) {
 34	  const user = await requireUser();
 35	  const { ticket: initialTicketId, dm: initialDmId } = await searchParams;
 36	  const monthAgo = new Date(Date.now() - 30 * 86_400_000);
 37	
 38	  const [tickets, closedRecently, firstStaffReplies, helpData, health, uptime, incidents] = await Promise.all([
 39	    db.ticket.findMany({
 40	      where: { userId: user.id },
 41	      select: {
 42	        id: true, subject: true, status: true, priority: true,
 43	        createdAt: true, updatedAt: true,
 44	      },
 45	      orderBy: { updatedAt: "desc" },
 46	      take: 40,
 47	    }),
 48	    db.ticket.count({
 49	      where: { userId: user.id, status: "CLOSED", updatedAt: { gte: monthAgo } },
 50	    }),
 51	    db.ticketMessage.groupBy({
 52	      by: ["ticketId"],
 53	      where: { ticket: { userId: user.id }, isStaff: true },
 54	      _min: { createdAt: true },
 55	    }),
 56	    getHelpData(),
 57	    getHealth(),
 58	    uptimeSummary(),
 59	    listIncidents(),
 60	  ]);
 61	
 62	  /* Staff-initiated direct messages (StaffDm) — a separate, much smaller
 63	     inbox from the ticket list above (see prisma/schema.prisma's StaffDm
 64	     doc comment for why it's not just another Ticket row). Unlike the
 65	     ticket list's two-step preview fetch, a nested `take: 1` here is fine:
 66	     this is one customer's own handful of DM threads, not a global queue. */
 67	  const staffDmRows = (await db.staffDm.findMany({
 68	    where: { userId: user.id },
 69	    select: {
 70	      id: true,
 71	      subject: true,
 72	      status: true,
 73	      updatedAt: true,
 74	      unreadForCustomer: true,
 75	      messages: { orderBy: { createdAt: "desc" }, take: 1, select: { body: true, isStaff: true } },
 76	    },
 77	    orderBy: { updatedAt: "desc" },
 78	    take: 40,
 79	  })) as {
 80	    id: string;
 81	    subject: string;
 82	    status: string;
 83	    updatedAt: Date;
 84	    unreadForCustomer: boolean;
 85	    messages: { body: string; isStaff: boolean }[];
 86	  }[];
 87	  const dms: DmSummary[] = staffDmRows.map((dm) => ({
 88	    id: dm.id,
 89	    subject: dm.subject,
 90	    status: dm.status,
 91	    updatedAt: dm.updatedAt.toISOString(),
 92	    unreadForCustomer: dm.unreadForCustomer,
 93	    preview: (dm.messages[0]?.body ?? "").replace(/\s+/g, " ").slice(0, 120),
 94	  }));
 95	
 96	  /* The latest message per ticket, for the list preview. This used to ride
 97	     along as a nested `messages: { orderBy, take: 1 }` select on the ticket
 98	     query above — but Prisma's default ("query") relation strategy has no
 99	     SQL-level LIMIT per parent for a nested to-many `take`: it fetches EVERY
100	     TicketMessage row (full `body` text included) for all 40 tickets via a
101	     single `ticketId IN (...)` query, orders it, and only then discards all
102	     but the newest per ticket. For a long-running ticket thread that is a lot
103	     of wasted body bytes pulled over the wire and thrown away. Instead: get
104	     just the max(createdAt) per ticket (a cheap aggregate, no body), then
105	     fetch exactly those rows — at most one per ticket. */
106	  const ticketIds = tickets.map((t) => t.id);
107	  const lastMessageMeta = ticketIds.length
108	    ? await db.ticketMessage.groupBy({
109	        by: ["ticketId"],
110	        where: { ticketId: { in: ticketIds } },
111	        _max: { createdAt: true },
112	      })
113	    : [];
114	  const lastMessages = lastMessageMeta.length
115	    ? await db.ticketMessage.findMany({
116	        where: {
117	          OR: lastMessageMeta
118	            .filter((m) => m._max.createdAt)
119	            .map((m) => ({ ticketId: m.ticketId, createdAt: m._max.createdAt! })),
120	        },
121	        select: { ticketId: true, body: true, isStaff: true, createdAt: true },
122	      })
123	    : [];
124	  const lastMessageByTicket = new Map(lastMessages.map((m) => [m.ticketId, m]));
125	
126	  const rows = tickets.map((t) => {
127	    const last = lastMessageByTicket.get(t.id);
128	    return {
129	      id: t.id,
130	      subject: t.subject,
131	      status: t.status,
132	      priority: t.priority,
133	      updated: t.updatedAt.toISOString(),
134	      /* The last message, trimmed for the list. Staff or customer is marked so a
135	         reader can tell at a glance whose move it is. */
136	      preview: last?.body.replace(/\s+/g, " ").slice(0, 120) ?? "",
137	      lastFromStaff: last?.isStaff ?? false,
138	    };
139	  });
140	
141	  const firstReplyByTicket = new Map(firstStaffReplies.map((r) => [r.ticketId, r._min.createdAt]));
142	  const responseMinutes: number[] = [];
143	  for (const t of tickets) {
144	    const firstStaffAt = firstReplyByTicket.get(t.id);
145	    if (firstStaffAt) responseMinutes.push((firstStaffAt.getTime() - t.createdAt.getTime()) / 60000);
146	  }
147	  const avgResponseMin = responseMinutes.length > 0
148	    ? Math.round(responseMinutes.reduce((a, b) => a + b, 0) / responseMinutes.length)
149	    : null;
150	
151	  const help = helpData.sections.map((s) => ({
152	    name: s.category.name,
153	    slug: s.category.slug,
154	    emoji: s.category.emoji,
155	    blurb: s.category.blurb,
156	    count: s.posts.length,
157	  }));
158	
159	  /* Combine open + resolved into one recent-incidents list, newest first,
160	     capped small — this is a support tab, not the full status page. */
161	  const recentIncidents = [...incidents.open, ...incidents.resolved]
162	    .sort((a, b) => new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime())
163	    .slice(0, 6);
164	
165	  return (
166	    <SupportView
167	      viewer={{ name: user.name ?? null, email: user.email ?? null }}
168	      viewerId={user.id}
169	      tickets={rows}
170	      open={rows.filter((t) => t.status !== "CLOSED").length}
171	      /* "Waiting for you" is ANSWERED — staff replied and the ball is in the
172	         customer's court. That is the state worth surfacing; it is the one they
173	         can act on. */
174	      waitingOnYou={rows.filter((t) => t.status === "ANSWERED").length}
175	      closedRecently={closedRecently}
176	      avgResponseMin={avgResponseMin}
177	      initialTicketId={initialTicketId ?? null}
178	      dms={dms}
179	      initialDmId={initialDmId ?? null}
180	      help={help}
181	      helpTotal={helpData.total}
182	      status={{
183	        overall: overallStatus(health),
184	        components: HEALTH_COMPONENTS.map((key) => ({
185	          key,
186	          label: COMPONENT_LABELS[key],
187	          status: health[key].status,
188	          uptimePct: uptime[key].pct,
189	        })),
190	        incidents: recentIncidents.map((inc) => ({
191	          id: inc.id,
192	          title: inc.title,
193	          body: inc.body,
194	          severity: inc.severity,
195	          startedAt: inc.startedAt,
196	          resolvedAt: inc.resolvedAt,
197	        })),
198	      }}
199	    />
200	  );
201	}

