/** Whether the OTHER party (relative to whoever's asking) is typing right now. */
export async function getTypingStatus(ticketId: string): Promise<{ typing: boolean }> {
  const user = await requireTicketActor();
  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
  if (!ticket) return { typing: false };
  if (ticket.userId !== user.id && !user.isSupportStaff) return { typing: false };
  const viewerIsStaff = user.isSupportStaff && ticket.userId !== user.id;
  const ping = typingPings.get(ticketId);
  if (!ping) return { typing: false };
  const at = viewerIsStaff ? ping.customerAt : ping.staffAt;
  return { typing: Date.now() - at < TYPING_TTL_MS };
}

